        for (i = 0; i < opt_state->edgewords; ++i) {
                register bpf_u_int32 x = ep->edom[i];

                while (x != 0) {
                        k = lowest_set_bit(x);
                        x &=~ ((bpf_u_int32)1 << k);
                        k += i * BITS_PER_WORD;

                        target = fold_edge(ep->succ, opt_state->edges[k]);
                        /*
                         * Check that there is no data dependency between
                         * nodes that will be violated if we move the edge.
